-- Migration 104: Fall Hiking Spree data checked against its sources (#778)
--
-- 1. Summit County resident ZIPs. The lists in migration 101 were written from
--    memory. Checked against the Census Bureau's 2020 ZIP Code Tabulation Areas
--    and Summit County's outline (TIGERweb, retrieved 2026-10-14): every ZCTA
--    that crosses the county line, and how much of it lies inside.
--    - 44141 (Brecksville) has about 8% of its area in Summit (the Sagamore Hills
--      and Northfield Center side) and was ticked No; it is now on the line.
--    - 44278 (Tallmadge) has about 5% in Portage County, as the city does, and
--      44321 (Copley) about 4% in Medina; both were ticked Yes and are now on
--      the line.
--    - The rest held: 443xx, and the listed ZIPs, are inside the county but for
--      slivers of 1-2% where a ZIP boundary does not follow the county line
--      (Stow, Hudson, Barberton, Fairlawn, Ellet); those stay Yes. 44210, 44222
--      and 44237 are post-office-box ZIPs inside the county with no ZCTA.
--    Changed only while the lists are still 101's, so an admin's edit stands.
-- 2. A list item can carry the line of the hike itself when it is shorter than
--    its trail. The Towpath item is the 1.09 miles from the Wilbeth Road
--    Trailhead to Summit Lake Nature Center (the form's 2.2 miles is there and
--    back), cut from the Towpath's own line; its tile drew all of the Towpath.
-- Idempotent.

UPDATE poi_lists
SET form_layout = jsonb_set(jsonb_set(form_layout,
      '{resident,zips}', '["44056", "44067", "44087", "44203", "44210", "44221", "44222", "44223", "44224", "44232", "44236", "44237", "44250", "44262", "44264", "44286"]'::jsonb),
      '{resident,unsureZips}', '["44141", "44202", "44216", "44230", "44240", "44260", "44278", "44281", "44321", "44614", "44685", "44720"]'::jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE series = 'fall-hiking-spree' AND edition = 2026
  AND form_layout->'resident'->'zips' = '["44056", "44067", "44087", "44203", "44210", "44221", "44222", "44223", "44224", "44232", "44236", "44237", "44250", "44262", "44264", "44278", "44286"]'::jsonb;

ALTER TABLE poi_list_items ADD COLUMN IF NOT EXISTS geometry JSONB;

